#!/usr/bin/env python3
"""Cross-model SC Ablation: test whether cross-model majority vote
replicates NLI combo gains (ensemble diversity vs structural independence)."""

import json
import os
from collections import Counter
from scipy.stats import binomtest

CLASSES = sorted(["True", "False", "Unknown"])
WEIGHTS = [1, 3, 5]

BASE = "/root/symb_invariant_consensus"

ID_FIX_PW = {
    "ProofWriter_AttNeg-OWA-D5-1176_Q8": "ProofWriter_AttNeg-OWA-D5-1176_Q4",
    "ProofWriter_AttNoneg-OWA-D5-1284_Q8": "ProofWriter_AttNoneg-OWA-D5-1284_Q4",
}

PW_GENERATORS = {
    "Mistral-7B": {
        "type": "votes_file",
        "path": f"{BASE}/data/mistral_pw600_sc_votes.json",
        "gt_source": f"{BASE}/data/proofwriter_full.json",
    },
    "LLaMA-8B": {
        "type": "results_json",
        "path": f"{BASE}/results/exp048_llama8b_pw600/exp048_results.json",
    },
    "Qwen2.5-14B": {
        "type": "results_json",
        "path": f"{BASE}/results/exp032_qwen25_14b_pw600/results.json",
    },
    "Qwen3-14B": {
        "type": "results_json",
        "path": f"{BASE}/results/exp033_qwen3_14b_pw600_nonthinking/results.json",
    },
}

FOLIO_GENERATORS = {
    "Mistral-7B": {
        "type": "results_json",
        "path": f"{BASE}/results/exp033_mistral_7b_folio204/exp033_results.json",
    },
    "LLaMA-8B": {
        "type": "results_json",
        "path": f"{BASE}/results/exp-063-llama8b-folio204-16639/results.json",
    },
    "Qwen2.5-14B": {
        "type": "results_json",
        "path": f"{BASE}/results/exp036_qwen25_14b_folio204/results.json",
    },
    "Qwen3-14B": {
        "type": "results_json",
        "path": f"{BASE}/results/exp_folio_2x2_qwen3/results.json",
    },
}

CROSS_VOTER = {
    "Mistral-7B": "Qwen2.5-14B",
    "LLaMA-8B": "Qwen2.5-14B",
    "Qwen2.5-14B": "LLaMA-8B",
    "Qwen3-14B": "Qwen2.5-14B",
}

NLI_COMBO_REF = {
    "ProofWriter": {
        "Mistral-7B":   {"w1": None, "w3": {"acc": 0.4600, "delta_pp": 6.67, "p": 0.0000113}, "w5": None},
        "LLaMA-8B":     {"w1": None, "w3": {"acc": 0.7333, "delta_pp": 0.83, "p": 0.665}, "w5": None},
        "Qwen2.5-14B":  {"w1": None, "w3": {"acc": 0.7467, "delta_pp": 0.67, "p": 0.503}, "w5": None},
        "Qwen3-14B":    {"w1": None, "w3": {"acc": 0.8633, "delta_pp": 0.50, "p": 0.453}, "w5": None},
    },
    "FOLIO": {
        "Mistral-7B":   {"w1": None, "w3": {"acc": 0.5882, "delta_pp": 2.94, "p": 0.210}, "w5": None},
        "LLaMA-8B":     {"w1": None, "w3": {"acc": 0.6520, "delta_pp": -0.98, "p": 0.824}, "w5": None},
        "Qwen2.5-14B":  {"w1": None, "w3": {"acc": 0.7549, "delta_pp": -0.49, "p": 1.0}, "w5": None},
        "Qwen3-14B":    {"w1": None, "w3": {"acc": 0.8480, "delta_pp": 1.47, "p": 0.25}, "w5": None},
    },
}


def sc_alpha(dist):
    max_v = max(dist.get(c, 0) for c in CLASSES)
    tied = [c for c in CLASSES if dist.get(c, 0) == max_v]
    return sorted(tied)[0]


def mcnemar_2sided(b, c):
    n = b + c
    if n == 0:
        return 1.0
    return binomtest(min(b, c), n, 0.5).pvalue


def load_generator_data(config, dataset):
    """Returns dict: pid -> {gt, sc_vote_dist}"""
    data = {}
    if config["type"] == "votes_file":
        pw_data = json.load(open(config["gt_source"]))
        gt = {q["id"]: q["answer"] for q in pw_data}
        votes_raw = json.load(open(config["path"]))
        for pid in sorted(gt.keys()):
            lookup = ID_FIX_PW.get(pid, pid)
            v = votes_raw.get(lookup, [0, 0, 0])
            data[pid] = {
                "gt": gt[pid],
                "sc_vote_dist": {"True": v[0], "False": v[1], "Unknown": v[2]},
            }
    else:
        d = json.load(open(config["path"]))
        for r in d["results"]:
            pid = r["problem_id"]
            data[pid] = {
                "gt": r["ground_truth"],
                "sc_vote_dist": r["sc_vote_distribution"],
            }
    return data


def run_cross_model_sc(gen_name, gen_data, cross_data, dataset_name):
    cross_voter_name = CROSS_VOTER[gen_name]
    pids = sorted(gen_data.keys())
    n = len(pids)

    # Compute cross-model's SC answer per problem
    cross_sc_answers = {}
    for pid in pids:
        if pid not in cross_data:
            cross_sc_answers[pid] = None
        else:
            cross_sc_answers[pid] = sc_alpha(cross_data[pid]["sc_vote_dist"])

    # SC baseline
    sc_correct_list = []
    for pid in pids:
        sc_pred = sc_alpha(gen_data[pid]["sc_vote_dist"])
        sc_correct_list.append(sc_pred == gen_data[pid]["gt"])
    sc_correct_n = sum(sc_correct_list)
    sc_acc = sc_correct_n / n

    results = {
        "generator": gen_name,
        "cross_voter": cross_voter_name,
        "dataset": dataset_name,
        "n": n,
        "sc_accuracy": round(sc_acc, 4),
        "sc_correct": sc_correct_n,
    }

    for w in WEIGHTS:
        combo_correct_list = []
        b_count = 0  # combo right, SC wrong
        c_count = 0  # combo wrong, SC right

        for i, pid in enumerate(pids):
            gold = gen_data[pid]["gt"]
            sc_dist = gen_data[pid]["sc_vote_dist"]
            sc_pred = sc_alpha(sc_dist)
            sc_ok = sc_pred == gold

            cross_ans = cross_sc_answers[pid]
            if cross_ans is None:
                combo_pred = sc_pred
            else:
                combo_dist = {c: sc_dist.get(c, 0) for c in CLASSES}
                combo_dist[cross_ans] = combo_dist.get(cross_ans, 0) + w
                combo_pred = sc_alpha(combo_dist)

            combo_ok = combo_pred == gold
            combo_correct_list.append(combo_ok)

            if combo_ok and not sc_ok:
                b_count += 1
            if not combo_ok and sc_ok:
                c_count += 1

        combo_correct_n = sum(combo_correct_list)
        combo_acc = combo_correct_n / n
        delta = combo_acc - sc_acc
        p_val = mcnemar_2sided(c_count, b_count)

        nli_ref = NLI_COMBO_REF.get(dataset_name, {}).get(gen_name, {}).get(f"w{w}")

        wkey = f"w{w}"
        results[f"cross_sc_{wkey}"] = round(combo_acc, 4)
        results[f"cross_sc_{wkey}_correct"] = combo_correct_n
        results[f"cross_sc_{wkey}_delta_pp"] = round(delta * 100, 2)
        results[f"cross_sc_{wkey}_mcnemar_p"] = round(p_val, 6)
        results[f"cross_sc_{wkey}_discordant"] = [c_count, b_count]

        if nli_ref:
            results[f"nli_combo_{wkey}_acc"] = nli_ref["acc"]
            results[f"nli_combo_{wkey}_delta_pp"] = nli_ref["delta_pp"]
            results[f"nli_combo_{wkey}_p"] = nli_ref["p"]

    return results


def main():
    all_results = []

    for dataset_name, generators in [("ProofWriter", PW_GENERATORS), ("FOLIO", FOLIO_GENERATORS)]:
        print(f"\n{'='*70}")
        print(f"  Dataset: {dataset_name}")
        print(f"{'='*70}")

        # Load all generator data for this dataset
        all_gen_data = {}
        for gen_name, config in generators.items():
            all_gen_data[gen_name] = load_generator_data(config, dataset_name)
            n = len(all_gen_data[gen_name])
            sc_ok = sum(1 for pid in all_gen_data[gen_name]
                        if sc_alpha(all_gen_data[gen_name][pid]["sc_vote_dist"]) == all_gen_data[gen_name][pid]["gt"])
            print(f"  Loaded {gen_name}: {n} problems, SC={sc_ok/n*100:.2f}%")

        for gen_name in generators:
            cross_voter_name = CROSS_VOTER[gen_name]
            cross_config = generators[cross_voter_name]
            cross_data = all_gen_data[cross_voter_name]

            print(f"\n--- {gen_name} + cross-voter: {cross_voter_name} ---")
            result = run_cross_model_sc(gen_name, all_gen_data[gen_name], cross_data, dataset_name)
            all_results.append(result)

            print(f"  SC baseline: {result['sc_accuracy']*100:.2f}% ({result['sc_correct']}/{result['n']})")
            for w in WEIGHTS:
                wk = f"w{w}"
                acc = result[f"cross_sc_{wk}"]
                delta = result[f"cross_sc_{wk}_delta_pp"]
                p = result[f"cross_sc_{wk}_mcnemar_p"]
                disc = result[f"cross_sc_{wk}_discordant"]
                line = f"  Cross-SC w={w}: {acc*100:.2f}% (Δ={delta:+.2f}pp, p={p:.4f}, disc={disc})"
                nli_acc = result.get(f"nli_combo_{wk}_acc")
                if nli_acc is not None:
                    nli_delta = result[f"nli_combo_{wk}_delta_pp"]
                    line += f"  |  NLI combo: {nli_acc*100:.2f}% (Δ={nli_delta:+.2f}pp)"
                print(line)

    # Summary comparison table
    print(f"\n{'='*70}")
    print("  SUMMARY: Cross-model SC (w=3) vs NLI combo (w=3)")
    print(f"{'='*70}")
    print(f"{'Generator':<16} {'Dataset':<12} {'SC':>7} {'Cross-SC':>9} {'Δ_cross':>8} {'NLI-combo':>10} {'Δ_NLI':>7} {'Cross/NLI':>10}")
    print("-" * 85)
    for r in all_results:
        sc = r["sc_accuracy"] * 100
        cross = r["cross_sc_w3"] * 100
        d_cross = r["cross_sc_w3_delta_pp"]
        nli = r.get("nli_combo_w3_acc")
        if nli is not None:
            d_nli = r["nli_combo_w3_delta_pp"]
            ratio = d_cross / d_nli if abs(d_nli) > 0.01 else float('inf')
            print(f"{r['generator']:<16} {r['dataset']:<12} {sc:6.2f}% {cross:8.2f}% {d_cross:+7.2f}pp {nli*100:9.2f}% {d_nli:+6.2f}pp {ratio:9.2f}x")
        else:
            print(f"{r['generator']:<16} {r['dataset']:<12} {sc:6.2f}% {cross:8.2f}% {d_cross:+7.2f}pp {'N/A':>10} {'N/A':>7} {'N/A':>10}")

    # Interpretation
    print(f"\n{'='*70}")
    print("  INTERPRETATION")
    print(f"{'='*70}")
    pw_results = [r for r in all_results if r["dataset"] == "ProofWriter"]
    cross_deltas = [r["cross_sc_w3_delta_pp"] for r in pw_results]
    nli_deltas = [r["nli_combo_w3_delta_pp"] for r in pw_results if r.get("nli_combo_w3_delta_pp") is not None]
    print(f"  PW avg cross-SC Δ(w=3): {sum(cross_deltas)/len(cross_deltas):+.2f}pp")
    print(f"  PW avg NLI-combo Δ(w=3): {sum(nli_deltas)/len(nli_deltas):+.2f}pp")
    if abs(sum(nli_deltas)/len(nli_deltas)) > 0.01:
        ratio = (sum(cross_deltas)/len(cross_deltas)) / (sum(nli_deltas)/len(nli_deltas))
        print(f"  Ratio (cross/NLI): {ratio:.2f}x")

    # Save
    output_path = f"{BASE}/results/cross_model_sc_ablation.json"
    output = {
        "experiment": "Cross-model SC Ablation",
        "description": "Test whether cross-model majority vote replicates NLI combo gains",
        "cross_voter_pairing": CROSS_VOTER,
        "weights": WEIGHTS,
        "results": all_results,
    }
    with open(output_path, "w") as f:
        json.dump(output, f, indent=2)
    print(f"\nSaved to {output_path}")


if __name__ == "__main__":
    main()
